import{_ as a,o as s,c as t,a6 as i}from"./chunks/framework.CKIbuWFA.js";const k=JSON.parse('{"title":"イベントの正規化・バッチ・欠落","description":"","frontmatter":{"title":"イベントの正規化・バッチ・欠落","docId":"developer.events","translationKey":"developer.events","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"caded5529a62e826a91d2deb86936c29c709ac713c2a0cd021f467b1dfa2b6e7","translationRevision":"45983681dff981890e7bff9bddc6d0f5d341c32f530b2b7f4a59c18ecc87bd4c","order":100},"headers":[],"relativePath":"ja/developer/events.md","filePath":"ja/developer/events.md","lastUpdated":1794611623000}'),o={name:"ja/developer/events.md"};function l(n,e,r,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="event-normalization-batches-and-gaps" tabindex="-1">イベントの正規化・バッチ・欠落 <a class="header-anchor" href="#event-normalization-batches-and-gaps" aria-label="Permalink to &quot;イベントの正規化・バッチ・欠落 {#event-normalization-batches-and-gaps}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>二重計上や表示復旧と実行の混同を避けて LIVE イベントを利用します。<a href="./storage.html">永続化</a> を理解し、実アカウントの記録ではなく無害化したフィクスチャーを使います。<code>tiktools-tiktok</code> は固定された署名・デコード依存関係を包み、安定した TikTools の値を公開します。コアは protobuf オブジェクトをアプリ API として公開しません。</p><h2 id="follow-the-implemented-pipeline" tabindex="-1">実装された流れを追う <a class="header-anchor" href="#follow-the-implemented-pipeline" aria-label="Permalink to &quot;実装された流れを追う {#follow-the-implemented-pipeline}&quot;">​</a></h2><p>取り込みは非同期処理の前に元の配信者・ルーム接続の文脈を保持します。正規化はチャット、ギフト、いいね、交流、ライフサイクルの値を生成します。コアは元のイベントを公開し、計上・実処理を別管理します。プロセッサーは <code>event.intel</code> に制限付き派生証拠を付けられ、失敗時も生イベントを劣化診断付きで保持します。生成自動化契約は実際に送出されるフィールドだけを記述します。</p><p>バックエンドの再送識別には配信者、ルーム、メソッド、型、ゼロ以外のメッセージ ID を使います。ID がなければ再送と確定できません。ギフトコンボの計上は送信者・ギフト・グループと累積最大値を使い、最終パケットで同量を二重付与しません。不明な価格はゼロです。集計遷移は <code>previous &lt; threshold &lt;= total</code> による閾値越えを支援できますが、公開する元イベントの代わりにはなりません。</p><h2 id="implement-a-consumer" tabindex="-1">受信側を実装する <a class="header-anchor" href="#implement-a-consumer" aria-label="Permalink to &quot;受信側を実装する {#implement-a-consumer}&quot;">​</a></h2><ol><li><code>src/automation/contracts/generated/</code> の型か、その境界用のウィジェットドメイン包みのパーサーを使います。</li><li>直列化を通して配信カーソルを保持し、リアルタイムと補完をつなぐ際に重複を除きます。</li><li>イベントごとに再描画せず、順序付きバッチを処理します。</li><li>欠落・過負荷を明示します。制限付きページや新しいスナップショットで表示を復旧し、ポイントやアクションを再実行しません。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automation</span></span></code></pre></div><p><a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-core/src/contracts" target="_blank" rel="noreferrer">Rust 契約ソース</a> がレジストリ、スキーマ、サンプルを生成します。完全なフィールド表を手で複製しないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>ID 付きイベントが現在の有限 replay store に残る間だけ、再接続の重複を排除します。待機列、カウンター、履歴、再送キャッシュには上限があります。無制限アーカイブや普遍的な厳密1回保証ではありません。容量不足や永続化不能は健全性に明示的な影響を与えます。</p><h2 id="recover-and-verify" tabindex="-1">復旧と検証 <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;復旧と検証 {#recover-and-verify}&quot;">​</a></h2><p>無害化したギフト・エモートのフィクスチャーで、最終コンボ、ID 不足、別ルームの識別、再接続の欠落を検査します。古い信頼性報告からハッシュをコピーせず、現在の <code>Cargo.toml</code> の署名依存リビジョンを確認します。未知の配信元メソッドは、正規化と生成契約で意図的に追加するまで未知のまま扱います。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>現在の既定値（2026-11-13）は実装上の制限で、SLA ではありません。LIVE 入口は 2,048 件、副作用キューは 128 件で、バイト上限ではありません。ライフサイクルイベントは空きを待ちます。ギフト・フォロー・シェアは最大 1 秒待ってから欠落を記録して破棄し、チャット・いいね・参加・その他は飽和時に即時破棄します。<code>droppedCritical</code>、いいねのバッチ・単位、副作用の欠落数を確認します。入力の欠落では副作用自体が未実行の場合があります。Backfill は表示だけを回復し、ポイントやアクションを補完しません。</p><p>重複排除はプロセス内で最大 4,096 ID を 300 秒保持し、そのストアが存続する間だけ再接続をまたぎます。期限切れ、容量による削除、ID 不在、再起動では保護されません。再接続の重複に対する保護もこの範囲内です。</p><p><code>ui.feed.backfill</code> は <code>{version:1,after:0,limit:64}</code> を受け取り、全体の数値カーソルと 1–512 の上限を使います。<code>oldestCursor</code>、<code>latestCursor</code>、<code>gap</code>、<code>truncated</code> を調べ、最後のイベントカーソルから続けます。<code>ui.feed.creator</code> は <code>{creatorId,streamId,after,limit}</code>、配信者別ストリームと文字列カーソル、1–64 件とバイト予算を使います。両者を混用しません。ストリーム変更・削除、未来のカーソル、入口の欠落、<code>CreatorFeedUnavailable</code> では正規の表示状態を再取得し、履歴不足を明示します。副作用を再構築してはいけません。</p><p>TikTok はセッション、ルーム、ギフトカタログ、署名 bundle、socket の順に初期化します。設定は <code>TIKTOOLS_TIKTOK_SIGNING_BUNDLE</code>、<code>TIKTOOLS_TIKTOK_BUNDLE_CACHE</code>、<code>TIKTOOLS_TIKTOK_BUNDLE_URL</code> です。既定は 5 回、初期待機 2 秒、上限 30 秒。HTTP 429 は Retry-After または 30–300 秒へ増加する最小待機とジッターを使い、制限時の再試行は最大 2 回で、中止・枯渇後も待機を保持します。他は一時的な通信障害だけを再試行します。<code>Reconnecting { attempt, delay_ms }</code> と失敗段階を確認し、Cookie や非公開署名情報は共有しません。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>`,20)])])}const u=a(o,[["render",l]]);export{k as __pageData,u as default};
